   284		case lastSize < targetSize/2:
   285			lastLimit *= 2
   286		case lastSize > targetSize*2:
   287			lastLimit /= 2
   288		}
   289		if lastLimit == 0 {
   290			lastLimit = 1
   291		}
   292		return lastLimit
   293	}
